{"command": "cat > arn_driver3.c <<'EOF'
#include <immintrin.h>
typedef void (*dnaupd_t)(void*, double*, double*, int, int*, double*, double*);
/* SELL-4: nb blocks of 4 rows; block b has len[b] columns, entries stored
   column-major within block (4 values per step); rows[4*b+r] = output row (or -1). */
static void spmv(int nb, const int *bptr, const int *blen, const int *rows,
                 const int *cidx, const double *vals, const double *x, double *y) {
    for (int b = 0; b < nb; b++) {
        __m256d s = _mm256_setzero_pd();
        const int *ci = cidx + bptr[b];
        const double *vv = vals + bptr[b];
        int L = blen[b];
        for (int j = 0; j < L; j++) {
            __m128i id = _mm_loadu_si128((const __m128i*)(ci + 4*j));
            __m256d xv = _mm256_i32gather_pd(x, id, 8);
            __m256d p = _mm256_mul_pd(_mm256_loadu_pd(vv + 4*j), xv);
            s = _mm256_add_pd(s, p);
        }
        double o[4]; _mm256_storeu_pd(o, s);
        const int *r = rows + 4*b;
        for (int k = 0; k < 4; k++) if (r[k] >= 0) y[r[k]] = o[k];
    }
}
int run_dnaupd(dnaupd_t f, void *st, double *resid, double *v, int n, int *ipntr,
               double *workd, double *workl, int nb, const int *bptr, const int *blen,
               const int *rows, const int *cidx, const double *vals) {
    int *ido = (int*)((char*)st + 52);
    for (;;) {
        f(st, resid, v, n, ipntr, workd, workl);
        if (*ido == 1 || *ido == 5) {
            double *y = workd + ipntr[1];
            spmv(nb, bptr, blen, rows, cidx, vals, workd + ipntr[0], y);
        } else return *ido;
    }
}
EOF
cc -O2 -mavx2 -ffp-contract=off -shared -fPIC -o arn_driver3.so arn_driver3.c 2>/dev/null && echo ok"}

{"command": "cat > arn_driver4.c <<'EOF'
typedef void (*dnaupd_t)(void*, double*, double*, int, int*, double*, double*);
static void spmv(int n, const int *ip, const int *ix, const double *d, const double *x, double *y) {
    int i = 0;
    for (; i + 4 <= n; i += 4) {
        int a0=ip[i],a1=ip[i+1],a2=ip[i+2],a3=ip[i+3],a4=ip[i+4];
        int l0=a1-a0,l1=a2-a1,l2=a3-a2,l3=a4-a3;
        int m=l0; if(l1<m)m=l1; if(l2<m)m=l2; if(l3<m)m=l3;
        double s0=0,s1=0,s2=0,s3=0;
        for (int j=0;j<m;j++){
            s0+=d[a0+j]*x[ix[a0+j]]; s1+=d[a1+j]*x[ix[a1+j]];
            s2+=d[a2+j]*x[ix[a2+j]]; s3+=d[a3+j]*x[ix[a3+j]];
        }
        for (int j=m;j<l0;j++) s0+=d[a0+j]*x[ix[a0+j]];
        for (int j=m;j<l1;j++) s1+=d[a1+j]*x[ix[a1+j]];
        for (int j=m;j<l2;j++) s2+=d[a2+j]*x[ix[a2+j]];
        for (int j=m;j<l3;j++) s3+=d[a3+j]*x[ix[a3+j]];
        y[i]=s0;y[i+1]=s1;y[i+2]=s2;y[i+3]=s3;
    }
    for (; i < n; i++) { double s=0; for (int j=ip[i];j<ip[i+1];j++) s+=d[j]*x[ix[j]]; y[i]=s; }
}
int run_dnaupd(dnaupd_t f, void *st, double *resid, double *v, int n, int *ipntr,
               double *workd, double *workl, const int *indptr, const int *indices,
               const double *data) {
    int *ido = (int*)((char*)st + 52);
    for (;;) {
        f(st, resid, v, n, ipntr, workd, workl);
        if (*ido == 1 || *ido == 5) spmv(n, indptr, indices, data, workd + ipntr[0], workd + ipntr[1]);
        else return *ido;
    }
}
EOF
