#include <stddef.h>
void my_dcopy(const int*n,const double*x,const int*incx,double*y,const int*incy){
  int N=*n,ix=*incx,iy=*incy;
  if(ix==1&&iy==1){for(int i=0;i<N;i++)y[i]=x[i];return;}
  int kx=ix<0?(1-N)*ix:0, ky=iy<0?(1-N)*iy:0;
  for(int i=0;i<N;i++)y[ky+i*iy]=x[kx+i*ix];
}
void my_dscal(const int*n,const double*a,double*x,const int*incx){
  int N=*n,ix=*incx;double A=*a; if(ix<=0)return;
  for(int i=0;i<N;i++)x[i*ix]*=A;
}
void my_dgemv(const char*tr,const int*m,const int*n,const double*alpha,const double*a,const int*lda,
              const double*x,const int*incx,const double*beta,double*y,const int*incy){
  int M=*m,N=*n,L=*lda;double al=*alpha,be=*beta;
  int T=(*tr=='T'||*tr=='t'||*tr=='C'||*tr=='c');
  int lenx=T?M:N, leny=T?N:M; int ix=*incx,iy=*incy;
  if(M==0||N==0||(al==0.0&&be==1.0))return;
  int kx=ix>0?0:-(lenx-1)*ix, ky=iy>0?0:-(leny-1)*iy;
  if(be!=1.0){ if(be==0.0){for(int i=0;i<leny;i++)y[ky+i*iy]=0.0;} else {for(int i=0;i<leny;i++)y[ky+i*iy]*=be;} }
  if(al==0.0)return;
  if(!T){
    for(int j=0;j<N;j++){double t=al*x[kx+j*ix]; const double*aj=a+(size_t)j*L; for(int i=0;i<M;i++)y[ky+i*iy]+=t*aj[i];}
  } else {
    for(int j=0;j<N;j++){double t=0.0; const double*aj=a+(size_t)j*L; for(int i=0;i<M;i++)t+=aj[i]*x[kx+i*ix]; y[ky+j*iy]+=al*t;}
  }
}
