void dger_(const int*,const int*,const double*,const double*,const int*,const double*,const int*,double*,const int*);
static int iladlr(int m,int n,const double*a,int lda){
  if(m==0)return 0;
  if(a[m-1]!=0.0||a[m-1+(long)(n-1)*lda]!=0.0)return m;
  int r=0; for(int j=0;j<n;j++){int i=m; while(i>=1 && a[(i-1)+(long)j*lda]==0.0 && i>=1) i--; if(i>r)r=i;} return r;}
static int iladlc(int m,int n,const double*a,int lda){
  if(n==0)return 0;
  if(a[(long)(n-1)*lda]!=0.0||a[m-1+(long)(n-1)*lda]!=0.0)return n;
  for(int c=n;c>=1;c--){for(int i=0;i<m;i++) if(a[i+(long)(c-1)*lda]!=0.0) return c;} return 0;}
void my_dlarf(const char*side,const int*m,const int*n,const double*v,const int*incv,const double*tau,double*c,const int*ldc,double*work){
  int L=(*side=='L'||*side=='l'); int lastv=0,lastc=0; double t=*tau; int one=1; double done=1.0,dzero=0.0,mt=-t;
  if(t!=0.0){
    lastv=L?*m:*n; int iv = (*incv>0)? 1+(lastv-1)*(*incv) : 1;
    while(lastv>0 && v[iv-1]==0.0){lastv--; iv-=*incv;}
    if(L) lastc=iladlc(lastv,*n,c,*ldc); else lastc=iladlr(*m,lastv,c,*ldc);
  }
  if(lastv<=0) return;
  if(L){ if(lastc>0){ dgemv_("T",&lastv,&lastc,&done,c,ldc,v,incv,&dzero,work,&one); dger_(&lastv,&lastc,&mt,v,incv,work,&one,c,ldc);} }
  else { if(lastc>0){ dgemv_("N",&lastc,&lastv,&done,c,ldc,v,incv,&dzero,work,&one); dger_(&lastc,&lastv,&mt,work,&one,v,incv,c,ldc);} }
}
void my_dcopy(const int*n,const double*x,const int*incx,double*y,const int*incy){
  int N=*n,ix=*incx,iy=*incy;
  if(ix==1&&iy==1){for(int i=0;i<N;i++)y[i]=x[i];return;}
  int kx=ix<0?(1-N)*ix:0, ky=iy<0?(1-N)*iy:0;
  for(int i=0;i<N;i++)y[ky+i*iy]=x[kx+i*ix];
}
void my_dscal(const int*n,const double*a,double*x,const int*incx){
  int N=*n,ix=*incx;double A=*a; if(ix<=0)return;
  for(int i=0;i<N;i++)x[i*ix]*=A;
}
