  int r=0; for(int j=0;j<n;j++){int i=m; while(i>=1 && a[(i-1)+(long)j*lda]==0.0) i--; if(i>r)r=i;} return r;}
static int iladlc(int m,int n,const double*a,int lda){
  if(n==0)return 0;
  if(a[(long)(n-1)*lda]!=0.0||a[m-1+(long)(n-1)*lda]!=0.0)return n;
  for(int c=n;c>=1;c--){for(int i=0;i<m;i++) if(a[i+(long)(c-1)*lda]!=0.0) return c;} return 0;}
void my_dlarf(const char*side,const int*m,const int*n,const double*v,const int*incv,const double*tau,double*c,const int*ldc,double*work){
  int L=(*side=='L'||*side=='l'); int lastv=0,lastc=0; double t=*tau; int one=1; double done=1.0,dzero=0.0,mt=-t;
  int ld=*ldc;
  if(t!=0.0){
    lastv=L?*m:*n; int iv = (*incv>0)? 1+(lastv-1)*(*incv) : 1;
    while(lastv>0 && v[iv-1]==0.0){lastv--; iv-=*incv;}
    if(L) lastc=iladlc(lastv,*n,c,ld); else lastc=iladlr(*m,lastv,c,ld);
  }
  if(lastv<=0||lastc<=0) return;
  if(*incv==1 && lastv<=3){
    if(L){
      /* work(j) = sum_i C(i,j) v(i), plain sequential; C(i,j) = fma(mt*v(i), work(j), C(i,j)) */
      for(int j=0;j<lastc;j++){const double*cj=c+(long)j*ld; double s=0.0; for(int i=0;i<lastv;i++) s+=cj[i]*v[i]; work[j]=s;}
      double av[3]; for(int i=0;i<lastv;i++) av[i]=mt*v[i];
      for(int j=0;j<lastc;j++){double*cj=c+(long)j*ld; double w=work[j]; for(int i=0;i<lastv;i++) cj[i]=fma(av[i],w,cj[i]);}
    } else {
      /* work(i) = sum_j C(i,j) v(j) with Accelerate's order; C(i,j)=fma(mt*work(i), v(j), C(i,j)) */
      const double*c0=c,*c1=c+ld,*c2=c+2*(long)ld;
      if(lastv==1){for(int i=0;i<lastc;i++) work[i]=v[0]*c0[i];}
      else if(lastv==2){for(int i=0;i<lastc;i++) work[i]=v[0]*c0[i]+v[1]*c1[i];}
      else {for(int i=0;i<lastc;i++) work[i]=fma(v[2],c2[i],v[0]*c0[i])+v[1]*c1[i];}
      for(int i=0;i<lastc;i++){double a=mt*work[i]; for(int j=0;j<lastv;j++) c[i+(long)j*ld]=fma(a,v[j],c[i+(long)j*ld]);}
    }
    return;
  }
  if(L){ dgemv_("T",&lastv,&lastc,&done,c,ldc,v,incv,&dzero,work,&one); dger_(&lastv,&lastc,&mt,v,incv,work,&one,c,ldc);}
  else { dgemv_("N",&lastc,&lastv,&done,c,ldc,v,incv,&dzero,work,&one); dger_(&lastc,&lastv,&mt,work,&one,v,incv,c,ldc);}
}
void my_dcopy(const int*n,const double*x,const int*incx,double*y,const int*incy){
  int N=*n,ix=*incx,iy=*incy; if(N<=0)return;
  if(ix==1&&iy==1){for(int i=0;i<N;i++)y[i]=x[i];return;}
  int kx=ix<0?(1-N)*ix:0, ky=iy<0?(1-N)*iy:0;
  for(int i=0;i<N;i++)y[ky+i*iy]=x[kx+i*ix];
}
