static double cand(const double*a,const double*x,int M,int K,int f,int red,int tail){
  double s[64]={0}; int i=0; int body=M-(M%K);
  for(;i<body;i+=K) for(int k=0;k<K;k++) s[k]= f? fma(a[i+k],x[i+k],s[k]) : s[k]+a[i+k]*x[i+k];
