    dgemv_("T",&M,&N,&al,A,&M,x,&one,&be,y,&one);
    printf("N=%d:",N);
    for(int ki=0;ki<6;ki++)for(int f=0;f<2;f++)for(int red=0;red<3;red++)for(int tail=0;tail<3;tail++){
      int good=1; for(int j=0;j<N;j++) if(cand(A+j*M,x,M,Ks[ki],f,red,tail)!=y[j]) {good=0;break;}
      if(good) printf(" K%d f%d r%d t%d",Ks[ki],f,red,tail);
    }
    printf("\n");
  }
}
