#include <pthread.h>
#include <stdatomic.h>
typedef void (*dnaupd_t)(void*, double*, double*, int, int*, double*, double*);

typedef struct {
    const int *ip, *ix; const double *d;
    const double *volatile x; double *volatile y;
    int n, nt;
    int bounds[17];
    atomic_int gen, done, quit;
} shared_t;

static inline void rows(const shared_t *s, int r0, int r1, const double *x, double *y) {
    const int *ip = s->ip, *ix = s->ix; const double *d = s->d;
    for (int i = r0; i < r1; i++) {
        double acc = 0.0;
        for (int j = ip[i]; j < ip[i+1]; j++) acc += d[j] * x[ix[j]];
        y[i] = acc;
    }
}
typedef struct { shared_t *s; int id; } targ_t;
static void *worker(void *p) {
    targ_t *a = (targ_t*)p; shared_t *s = a->s; int id = a->id;
    int seen = 0;
    for (;;) {
        int g;
        while ((g = atomic_load_explicit(&s->gen, memory_order_acquire)) == seen) {
            if (atomic_load_explicit(&s->quit, memory_order_relaxed)) return 0;
            __builtin_ia32_pause();
        }
        seen = g;
        rows(s, s->bounds[id], s->bounds[id+1], s->x, s->y);
        atomic_fetch_add_explicit(&s->done, 1, memory_order_release);
    }
}

int run_dnaupd(dnaupd_t f, void *st, double *resid, double *v, int n, int *ipntr,
               double *workd, double *workl, const int *indptr, const int *indices,
               const double *data, int nt) {
    int *ido = (int*)((char*)st + 52);
    if (nt < 1) nt = 1; if (nt > 16) nt = 16;
    shared_t s; s.ip = indptr; s.ix = indices; s.d = data; s.n = n; s.nt = nt;
    atomic_init(&s.gen, 0); atomic_init(&s.done, 0); atomic_init(&s.quit, 0);
    /* balance by nnz */
    long nnz = indptr[n]; s.bounds[0] = 0; int r = 0;
    for (int t = 1; t < nt; t++) { long target = nnz * t / nt; while (r < n && indptr[r] < target) r++; s.bounds[t] = r; }
    s.bounds[nt] = n;
    pthread_t th[16]; targ_t ta[16];
    for (int t = 1; t < nt; t++) { ta[t].s = &s; ta[t].id = t; pthread_create(&th[t], 0, worker, &ta[t]); }
    int gen = 0, ret;
    for (;;) {
        f(st, resid, v, n, ipntr, workd, workl);
        if (*ido == 1 || *ido == 5) {
            const double *x = workd + ipntr[0]; double *y = workd + ipntr[1];
            if (nt > 1) {
                s.x = x; s.y = y;
                atomic_store_explicit(&s.done, 0, memory_order_relaxed);
                atomic_store_explicit(&s.gen, ++gen, memory_order_release);
                rows(&s, s.bounds[0], s.bounds[1], x, y);
                while (atomic_load_explicit(&s.done, memory_order_acquire) != nt - 1) __builtin_ia32_pause();
            } else rows(&s, 0, n, x, y);
        } else { ret = *ido; break; }
    }
    atomic_store(&s.quit, 1);
    for (int t = 1; t < nt; t++) pthread_join(th[t], 0);
    return ret;
}
