#include <pthread.h>
#include <stdatomic.h>
#include <stddef.h>
typedef void (*dnaupd_t)(void*, double*, double*, int, int*, double*, double*);
typedef void (*gemv_t)(const char*,const int*,const int*,const double*,const double*,const int*,const double*,const int*,const double*,double*,const int*);

static gemv_t real_gemv;
#define MAXT 16
/* ---- generic spin pool ---- */
typedef struct {
    int kind; /* 1 = spmv, 2 = gemv */
    /* spmv */
    const int *ip, *ix; const double *d; const double *x; double *y; int bounds[MAXT+1];
    /* gemv */
    char tr; int m, n, lda, incx, incy; double alpha, beta; const double *a; const double *gx; double *gy;
    int gb[MAXT+1];
} job_t;
static job_t J;
static int NT = 1;
static atomic_int GEN, DONE, QUIT;
static pthread_t TH[MAXT];

static inline void spmv_rows(int r0, int r1) {
    const int *ip = J.ip, *ix = J.ix; const double *d = J.d; const double *x = J.x; double *y = J.y;
    for (int i = r0; i < r1; i++) {
        double acc = 0.0;
        for (int j = ip[i]; j < ip[i+1]; j++) acc += d[j] * x[ix[j]];
        y[i] = acc;
    }
}
static inline void gemv_part(int id) {
    int s = J.gb[id], e = J.gb[id+1];
    if (e <= s) return;
    int cnt = e - s;
    if (J.tr == 'N') {   /* split rows */
        real_gemv(&J.tr, &cnt, &J.n, &J.alpha, J.a + s, &J.lda, J.gx, &J.incx, &J.beta, J.gy + s, &J.incy);
    } else {             /* split columns */
        real_gemv(&J.tr, &J.m, &cnt, &J.alpha, J.a + (size_t)s * J.lda, &J.lda, J.gx, &J.incx, &J.beta, J.gy + s, &J.incy);
    }
}
static inline void do_part(int id) {
    if (J.kind == 1) spmv_rows(J.bounds[id], J.bounds[id+1]); else gemv_part(id);
}
static void *worker(void *p) {
    int id = (int)(size_t)p; int seen = 0;
    for (;;) {
        int g;
        while ((g = atomic_load_explicit(&GEN, memory_order_acquire)) == seen) {
            if (atomic_load_explicit(&QUIT, memory_order_relaxed)) return 0;
            __builtin_ia32_pause();
        }
        seen = g;
        do_part(id);
        atomic_fetch_add_explicit(&DONE, 1, memory_order_release);
    }
}
static void dispatch(void) {
    atomic_store_explicit(&DONE, 0, memory_order_relaxed);
    atomic_fetch_add_explicit(&GEN, 1, memory_order_release);
    do_part(0);
    while (atomic_load_explicit(&DONE, memory_order_acquire) != NT - 1) __builtin_ia32_pause();
}

/* replacement dgemv: parallel for large unit-stride calls, identical per-element arithmetic */
int GEMV_MIN = 4000;
void par_dgemv(const char *tr, const int *m, const int *n, const double *alpha, const double *a, const int *lda,
               const double *x, const int *incx, const double *beta, double *y, const int *incy) {
    int M = *m, N = *n;
    int T = (*tr == 'T' || *tr == 't');
    int isN = (*tr == 'N' || *tr == 'n');
    if (NT <= 1 || (!T && !isN) || *incx != 1 || *incy != 1 || (long)M * N < GEMV_MIN) {
        real_gemv(tr, m, n, alpha, a, lda, x, incx, beta, y, incy); return;
    }
    J.kind = 2; J.tr = T ? 'T' : 'N'; J.m = M; J.n = N; J.lda = *lda; J.incx = 1; J.incy = 1;
    J.alpha = *alpha; J.beta = *beta; J.a = a; J.gx = x; J.gy = y;
    if (isN) {
        /* rows, chunks multiple of 8 */
        int per = ((M + NT - 1) / NT + 7) & ~7;
        for (int t = 0; t <= NT; t++) { int b = t * per; J.gb[t] = b > M ? M : b; }
    } else {
        /* columns, chunks multiple of 4 */
        int per = ((N + NT - 1) / NT + 3) & ~3;
        for (int t = 0; t <= NT; t++) { int b = t * per; J.gb[t] = b > N ? N : b; }
    }
    dispatch();
}

int run_dnaupd(dnaupd_t f, void *st, double *resid, double *v, int n, int *ipntr,
               double *workd, double *workl, const int *indptr, const int *indices,
               const double *data, int nt, gemv_t rg) {
    int *ido = (int*)((char*)st + 52);
    real_gemv = rg;
    if (nt < 1) nt = 1; if (nt > MAXT) nt = MAXT;
    NT = nt;
    J.ip = indptr; J.ix = indices; J.d = data;
    long nnz = indptr[n]; J.bounds[0] = 0; int r = 0;
    for (int t = 1; t < nt; t++) { long target = nnz * t / nt; while (r < n && indptr[r] < target) r++; J.bounds[t] = r; }
    J.bounds[nt] = n;
    atomic_store(&GEN, 0); atomic_store(&QUIT, 0);
    for (int t = 1; t < nt; t++) pthread_create(&TH[t], 0, worker, (void*)(size_t)t);
    int ret;
    for (;;) {
        f(st, resid, v, n, ipntr, workd, workl);
        if (*ido == 1 || *ido == 5) {
            J.x = workd + ipntr[0]; J.y = workd + ipntr[1];
            if (nt > 1) { J.kind = 1; dispatch(); } else spmv_rows(0, n);
        } else { ret = *ido; break; }
    }
    atomic_store(&QUIT, 1);
    for (int t = 1; t < nt; t++) pthread_join(TH[t], 0);
    NT = 1;
    return ret;
}
